{
  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C09"],
      "claim": "Camellianin B, a polyphenolic flavone glycoside, was detected in rat brain after intragastric administration of camellianin A, demonstrating that glycosylated polyphenols can achieve CNS exposure after systemic dosing.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C12"],
      "claim": "Cyanidin-3-O-glucoside reached approximately 3.5 nmol/g in mouse brain after intraperitoneal injection, providing quantitative evidence that a polar anthocyanin glycoside can achieve meaningful brain levels.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "After a 15-day blackberry anthocyanin-enriched diet, cyanidin-3-O-glucoside was the predominant anthocyanin in rat brain and was higher in brain than plasma, indicating brain uptake of a glycosylated polyphenol.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "Chlorogenic acid, rutin, and hyperoside were detected in rat brain after oral administration of an E. senticosus leaf extract, supporting brain access of polar glycosylated polyphenols.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C02"],
      "claim": "A phenylethanoid glycoside was detected in rat hippocampus and striatum after oral administration, showing that highly polar glycosides can cross the blood-brain barrier in vivo.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Mangiferin is a C-glucosylated xanthone polyphenol. Although no direct mangiferin brain PK record is provided, multiple independent in vivo studies demonstrate that structurally related glycosylated polyphenols—flavone glycosides, anthocyanin glycosides, rutin/hyperoside, and phenylethanoid glycosides—reach brain tissue after systemic administration. The consistent supportive evidence outweighs the physicochemical expectation of poor passive permeability, supporting a pass for meaningful CNS access.",
  "evidence_gaps": [
    "No direct quantitative brain exposure or brain-to-plasma ratio for mangiferin itself is provided.",
    "Potential efflux transporter involvement for mangiferin at the BBB is not directly assessed.",
    "Oral bioavailability of mangiferin may be low, and the visible evidence does not establish the exact route-dependent brain exposure."
  ],
  "new_evidence_assessment": [
    {
      "applicability": "high",
      "card_ids": ["C12"],
      "decision_effect": "strengthened",
      "direction": "supportive",
      "family": "anthocyanin glycoside brain distribution"
    },
    {
      "applicability": "moderate",
      "card_ids": ["C09"],
      "decision_effect": "strengthened",
      "direction": "supportive",
      "family": "flavone glycoside brain distribution"
    }
  ],
  "revision_action": "initial"
}

